import { defineComponent, h, type Component } from 'vue';
import { Motion } from 'motion-v';

/**
 * Renders its child, animated: the child takes the motion props (and the
 * other attributes) given to the Slot.
 */
const Slot = defineComponent({
  name: 'Slot',
  inheritAttrs: false,
  setup(_, { attrs, slots }) {
    return () => h(Motion as Component, { ...attrs, asChild: true }, slots);
  },
});

export { Slot };

import type { Transition } from 'motion-v';

import { motionTokens } from '../../utils/motion';

const SCALE_SPRING: Transition = motionTokens.spring.press;

const TAP_SCALE = motionTokens.scale.press;

export { SCALE_SPRING, TAP_SCALE };

import {
  cloneVNode,
  defineComponent,
  Fragment,
  h,
  inject,
  isVNode,
  mergeProps,
  onBeforeUnmount,
  onMounted,
  provide,
  ref,
  shallowRef,
  useId,
  watch,
  type Component,
  type InjectionKey,
  type PropType,
  type VNode,
} from 'vue';
import { AnimatePresence, motion, type Transition } from 'motion-v';

import {
  motionTokens,
  ReducedMotionConfig,
  useMotionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';

const HIGHLIGHT_TRANSITION: Transition = motionTokens.spring.highlight;

const INSTANT: Transition = { duration: 0 };

type HighlightMode = 'children' | 'parent';

type Bounds = {
  top: number;
  left: number;
  width: number;
  height: number;
};

type HighlightContextType = {
  mode: () => HighlightMode;
  activeValue: () => string | null;
  previousValue: () => string | null;
  changes: () => number;
  setActiveValue: (value: string | null) => void;
  setBounds: (bounds: DOMRect) => void;
  clearBounds: () => void;
  id: string;
  hover: () => boolean;
  click: () => boolean;
  className: () => unknown;
  style: () => unknown;
  setActiveClassName: (className: string) => void;
  transition: () => Transition;
  disabled: () => boolean;
  enabled: () => boolean;
  exitDelay: () => number;
  forceUpdateBounds: () => boolean | undefined;
  items: Set<HTMLElement>;
};

const HighlightKey: InjectionKey<HighlightContextType> =
  Symbol('AnimateUIHighlight');

function useHighlight() {
  const context = inject(HighlightKey, null);
  if (!context) throw new Error('useHighlight must be used within a Highlight');
  return context;
}

const HOVER_QUERY = '(hover: hover) and (pointer: fine)';

function useCanHover() {
  const canHover = ref(false);
  let query: MediaQueryList | null = null;
  const update = () => (canHover.value = query?.matches ?? false);
  onMounted(() => {
    query = window.matchMedia(HOVER_QUERY);
    update();
    query.addEventListener('change', update);
  });
  onBeforeUnmount(() => query?.removeEventListener('change', update));
  return canHover;
}

const M = motion as unknown as Record<string, Component>;

const ParentHighlight = defineComponent({
  name: 'ParentHighlight',
  props: {
    bounds: Object as PropType<Bounds | null>,
    transition: { type: Object as PropType<Transition>, required: true },
    exitDelay: { type: Number, required: true },
    surfaceClass: null,
    surfaceStyle: null,
  },
  setup(props) {
    const reduce = useShouldReduceMotion();
    return () => {
      const t = props.transition;
      const move: Transition = reduce.value
        ? { ...t, top: INSTANT, left: INSTANT, width: INSTANT, height: INSTANT }
        : t;
      const b = props.bounds;
      return h(
        AnimatePresence as Component,
        { initial: false, mode: 'wait' },
        () =>
          b
            ? h(M.div!, {
                'data-slot': 'motion-highlight',
                animate: { ...b, opacity: 1 },
                initial: { ...b, opacity: 0 },
